import{_ as o,o as i,c as d,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"插件示例","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/dev-guide/examples.md","filePath":"zh-HK/dev-guide/examples.md","lastUpdated":1785993908000}'),t={name:"zh-HK/dev-guide/examples.md"};function c(a,e,n,s,l,u){return i(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="插件示例" tabindex="-1">插件示例 <a class="header-anchor" href="#插件示例" aria-label="Permalink to &quot;插件示例&quot;">​</a></h1><p>Lertaro 自帶兩個插件，都是很有參考價值的真實案例——都在 Lertaro 倉庫的 <code>Plugins/</code> 目錄下。</p><h2 id="coreextensions-——-動作與-shell-右鍵選單" tabindex="-1">CoreExtensions —— 動作與 Shell 右鍵選單 <a class="header-anchor" href="#coreextensions-——-動作與-shell-右鍵選單" aria-label="Permalink to &quot;CoreExtensions —— 動作與 Shell 右鍵選單&quot;">​</a></h2><p><code>CoreExtensionsPlugin</code> 同時實現了三個接口:<code>IPlugin</code>、<code>IActionProvider</code>、<code>IConfigurable</code>。</p><ul><li><strong><code>IActionProvider.GetActions()</code></strong> 返回十個內置的 <code>ISearchResultAction</code>——打開、在檔案總管中定位、複製路徑、複製/剪下檔案本身、在其所在位置打開命令提示字元、touch/mkdir，以及打開和命令提示字元的提權(以系統管理員身份運行)變體。</li><li><strong><code>IActionProvider.GetDynamicActionProviders()</code></strong> 返回一個 <code>IDynamicActionProvider</code>—— <code>ShellMenuActionProvider</code>——正是它讓真正的 Windows 右鍵選單(包括&quot;發送到&quot;這類級聯子選單)出現在 Lertaro 自己的動作選單裏。如果你想在 Lertaro 裏呈現<em>任何</em>外部、動態構建的選單，而不是一份固定的動作列表，這是值得照抄的模式。</li><li><strong><code>IConfigurable.GetConfigSchema()</code></strong> 展示了帶嵌套欄位分組和 <code>StringList</code> 欄位類型的配置模式 ——如果你的插件在設定 → 插件的配置對話方塊裏需要的不只是一份扁平的布爾值列表，值得讀一下這部分。</li><li>有五個提供器實現了 <a href="./sdk/ui-extensions.html#iquickpaneltabprovider"><code>IQuickPanelTabProvider</code></a>，而且它們正好覆蓋了這個接口的兩端。<code>FavoritesTabProvider</code> 和 <code>HistoryTabProvider</code> 原樣交出一份記憶體裏的列表——最簡參考實現，因為兩者自己都沒有額外的狀態。<code>WindowsRecentTabProvider</code> 則是另一端：它在背景任務上讀目錄、透過 COM 解析 shell 捷徑，<strong>先</strong>截斷再做那件昂貴的事，並給每個項目填上 <code>Metadata.Modified</code>，好讓標籤的「最新在前」真的有意義。</li><li><code>LastDirectoryTabProvider</code> 和 <code>RecentFilesTabProvider</code> 值得讀的理由不太一樣：它們自己壓根沒有資料，而是透過 <a href="./sdk/services.html"><code>ExplorerPathService</code></a> 和 <code>RecentFilesService</code> 向宿主要。只要你的插件想展示的東西 Lertaro 本來就知道，照抄這個模式就對了。</li></ul><h2 id="pinyinalias-——-中文檔案名拼音別名" tabindex="-1">PinyinAlias —— 中文檔案名拼音別名 <a class="header-anchor" href="#pinyinalias-——-中文檔案名拼音別名" aria-label="Permalink to &quot;PinyinAlias —— 中文檔案名拼音別名&quot;">​</a></h2><p><code>PinyinAliasProvider</code> 同時實現了 <code>IAliasProvider</code> 和 <code>ITranslationProvider</code>——一個插件可以自由組合多個相關的 SDK 角色，這是個很好的參考模板:</p><ul><li><strong><code>IAliasProvider.InputRanges</code>/<code>OutputRanges</code></strong> 直接複用 <code>PinyinEngine</code> 自己表裏的邊界來聲明這兩個字母表(<code>InputRanges</code>:CJK 區塊;<code>OutputRanges</code>:<code>a</code>-<code>z</code>),不重複寫魔數——宿主用它們支援 &quot;大cj&quot;匹配&quot;大長今&quot;這類混合了字面漢字和拼音的查詢。</li><li><strong><code>IAliasProvider.CanHandle(text)</code></strong> 會先掃描是否存在任意中文字元，再決定要不要做實際工作，所以非中文檔案名會完全跳過別名生成。</li><li><strong><code>IAliasProvider.GetAliases(text)</code></strong> 先構建一張按字元劃分的音節表(每個漢字映射到它可能的拼音讀音)，然後產出一個全拼別名和一個首字母別名。對於含多音字(有一種以上有效讀音)的檔案名，會為每種常見讀音組合都生成別名——上限 32 種組合，防止極端輸入引發組合爆炸——用 <code>|</code> 連接各個備選項，這樣搜尋引擎會把每一個都當作候選，而不是要求它們同時全部匹配。</li><li><strong><code>ITranslationProvider</code></strong> 實現在<em>同一個</em>類上，純粹是為了給這個插件自己的介面文本(比如它的顯示名稱)提供翻譯，通過 <code>TranslationService.LoadEmbeddedTranslations</code> 實現——這兩個接口用途上並無關聯，只是碰巧在這個體量很小的單檔案插件裏放在了同一個類型上。</li><li>用一個 <code>lock</code> 保護的 <code>Dictionary&lt;string, Dictionary&lt;string, string&gt;&gt;</code> 快取避免了每次調用 <code>GetTranslations</code> 都重新解析內嵌的翻譯 JSON——這是任何在 <code>GetTranslations</code> 裏做了非平凡工作的插件都該採用的標準模式。</li></ul><p>把這兩個插件對照着看，是理解<a href="./sdk/core-search-actions.html">插件 SDK 參考</a>裏各個部分如何在實踐中配合起來最快的方式。</p>',9)])])}const P=o(t,[["render",c]]);export{h as __pageData,P as default};
